import fs from 'node:fs';import path from 'node:path';import {payloadHash} from '../../execution/ledger.mjs';import {verifyJournal,replayVariant} from '../../moloch/compare.mjs';
const json=p=>JSON.parse(fs.readFileSync(p,'utf8').replace(/^\uFEFF/,''));const episodes=[];
for(let i=18;i<=25;i++){const dir=`runtime/moloch/live-sig-20261014-${i}`,m=json(dir+'/manifest.json'),stats=json(dir+'/stats.json'),snap=json(dir+'/state.json'),{hash,...body}=snap;if(stats.status!=='completed'||stats.captureExit!==0||hash!==payloadHash(body))throw Error('invalid terminal');const p=json(path.join(m.continuation.parentDirectory,'state.json')),{hash:ph,...pb}=p;if(ph!==payloadHash(pb)||ph!==m.continuation.parentSnapshotHash)throw Error('parent');if(episodes.length&&ph!==episodes.at(-1).snapshot.hash)throw Error('continuity');const bytes=fs.readFileSync(dir+'/events.jsonl','utf8'),rows=bytes.trim().split(/\r?\n/).map(JSON.parse);episodes.push({i,manifest:m,snapshot:snap,parent:p,events:verifyJournal(rows,snap)});}
const cases=[['recorded',{}],['externalWideSpread',{insideTicks:0,minimumSpreadTicks:8,retainProfitableHedge:false,maximumHedgeOvershoot:0}],['externalImbalance30',{insideTicks:0,quoteMode:'microprice',minimumDepthImbalanceBps:3000,retainProfitableHedge:false,maximumHedgeOvershoot:0}],['externalCombined',{insideTicks:0,minimumSpreadTicks:8,quoteMode:'microprice',minimumDepthImbalanceBps:3000,retainProfitableHedge:false,maximumHedgeOvershoot:0}]];const compact=r=>({realized:r.report.realized,cash:r.report.cash,ownedCost:r.report.ownedCost,unresolvedOrders:r.report.unresolvedOrders,newFills:r.newFills.length,lastFresh:r.lastFreshLiquidation,worstFresh:r.worstFreshLiquidation,final:r.report.netLiquidationPnl});
const results=[];for(const [name,overrides]of cases){let state=structuredClone(episodes[0].parent.state);const marks=[];for(const e of episodes){const r=replayVariant(state,e.events,{...e.manifest.policy,...overrides});if(name==='recorded'){const clean=s=>{const{policy,policyHash,...rest}=s;return rest};if(payloadHash(clean(r.state))!==payloadHash(clean(e.snapshot.state)))throw Error('baseline parity '+e.i);}state=r.state;marks.push({episode:e.i,...compact(r)});}const result={name,overrides,marks};results.push(result);console.log(JSON.stringify(result));}
const train=results.filter(r=>!r.name.startsWith('queue')).map(r=>({name:r.name,mark:r.marks.find(m=>m.episode===20).lastFresh})).filter(r=>r.mark).sort((a,b)=>Number(b.mark.pnl)-Number(a.mark.pnl)||a.name.localeCompare(b.name));
const out={schemaVersion:1,source:'verified original paper episode journals',episodes:episodes.map(e=>({episode:e.i,parentHash:e.parent.hash,snapshotHash:e.snapshot.hash,from:e.manifest.cutoff,to:e.snapshot.state.lastAt,eventCount:e.events.length})),baselineFinancialParity:true,newPaperCapital:'0.000000',trainingEpisodes:[18,19,20],laterEpisodes:[21,22,23,24,25],trainRanking:train,results,contestOrders:0,profitabilityEstablished:false,limitations:['Retrospective chronological diagnostic; these periods were previously inspected and are not pristine holdouts.','Policies carry their own unchanged cash, orders and inventory across every episode. Historical captured markets do not adapt to hypothetical inventory.','Conditional queue variants are assumptions, not observed maker fills.','Last-fresh marks are timestamped and may precede episode end; no stale terminal liquidation is fabricated.','Selection ranking is training-only; no parameter is selected using later episode returns.']};fs.writeFileSync('runtime/moloch/external-strategies-20261014.json',JSON.stringify(out,null,2)+'\n');
